function crearDoble() {
  const raiz = {};
  raiz.siguiente = raiz;
  raiz.anterior = raiz;
  return raiz;
}

function ponerAntes(destino, valor) {
  const nodo = { valor, anterior: destino.anterior, siguiente: destino };
  nodo.anterior.siguiente = nodo;
  destino.anterior = nodo;
  return nodo;
}

function sacarDoble(nodo) {
  nodo.anterior.siguiente = nodo.siguiente;
  nodo.siguiente.anterior = nodo.anterior;
}

function crearLRU(capacidad) {
  const raiz = crearDoble();
  const indice = new Map();
  function promover(nodo) {
    sacarDoble(nodo);
    indice.set(nodo.valor.clave, ponerAntes(raiz, nodo.valor));
  }
  return {
    leer(clave) {
      const nodo = indice.get(clave);
      if (!nodo) return { acierto: false, valor: null };
      promover(nodo);
      return { acierto: true, valor: nodo.valor.valor };
    },
    guardar(clave, valor) {
      if (capacidad === 0) return;
      const nodo = indice.get(clave);
      if (nodo) {
        nodo.valor.valor = valor;
        promover(nodo);
        return;
      }
      if (indice.size === capacidad) {
        const expulsado = raiz.siguiente;
        sacarDoble(expulsado);
        indice.delete(expulsado.valor.clave);
      }
      indice.set(clave, ponerAntes(raiz, { clave, valor }));
    },
    orden() {
      const claves = [];
      for (let nodo = raiz.siguiente; nodo !== raiz; nodo = nodo.siguiente)
        claves.push(nodo.valor.clave);
      return claves;
    },
  };
}

function tablaPrefijos(patron) {
  const pi = Array(patron.length).fill(0);
  let largo = 0;
  for (let i = 1; i < patron.length; i++) {
    while (largo && patron[i] !== patron[largo]) largo = pi[largo - 1];
    if (patron[i] === patron[largo]) largo++;
    pi[i] = largo;
  }
  return pi;
}

function buscarKMP(texto, patron) {
  if (!patron.length)
    return Array.from({ length: texto.length + 1 }, (_, i) => i);
  const pi = tablaPrefijos(patron);
  const indices = [];
  let largo = 0;
  for (let i = 0; i < texto.length; i++) {
    while (largo && texto[i] !== patron[largo]) largo = pi[largo - 1];
    if (texto[i] === patron[largo]) largo++;
    if (largo === patron.length) {
      indices.push(i - patron.length + 1);
      largo = pi[largo - 1];
    }
  }
  return indices;
}

function canonizarNombre(texto) {
  return texto.trim().toLowerCase().normalize("NFC");
}

function indiceDeNombres(estaciones) {
  const porNombre = new Map();
  for (const [codigo, nombre] of estaciones) {
    const clave = canonizarNombre(nombre);
    if (!porNombre.has(clave)) porNombre.set(clave, []);
    porNombre.get(clave).push(codigo);
  }
  return porNombre;
}

function catalogoTesla(estaciones, acciones, capacidad) {
  const nombres = indiceDeNombres(estaciones);
  const cache = crearLRU(capacidad);
  const historia = [];
  const respuestas = [];
  for (const [modo, consulta] of acciones) {
    if (modo === "deshacer") {
      respuestas.push(historia.pop() ?? null);
      continue;
    }
    const clave = canonizarNombre(consulta);
    const claveCache = JSON.stringify([modo, clave]);
    const previa = cache.leer(claveCache);
    let codigos = previa.valor;
    if (!previa.acierto) {
      if (clave === "") codigos = [];
      else if (modo === "exacta") codigos = nombres.get(clave) ?? [];
      else {
        const aceptados = new Set();
        for (const nombre of nombres.keys()) {
          if (buscarKMP(nombre, clave).length) aceptados.add(nombre);
        }
        codigos = estaciones
          .filter(([, nombre]) => aceptados.has(canonizarNombre(nombre)))
          .map(([codigo]) => codigo);
      }
      cache.guardar(claveCache, codigos);
    }
    historia.push({ modo, clave, codigos });
    respuestas.push({ acierto: previa.acierto, codigos });
  }
  return { respuestas, historia };
}

function limiteHorario(datos, hora, despues = false) {
  let inicio = 0;
  let fin = datos.length;
  while (inicio < fin) {
    const medio = inicio + Math.floor((fin - inicio) / 2);
    const minuto = datos[medio];
    if (minuto < hora || (despues && minuto === hora)) inicio = medio + 1;
    else fin = medio;
  }
  return inicio;
}

function mezclarHorarios(a, b) {
  const salida = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (a[i][0] <= b[j][0]) salida.push(a[i++]);
    else salida.push(b[j++]);
  }
  for (; i < a.length; i++) salida.push(a[i]);
  for (; j < b.length; j++) salida.push(b[j]);
  return salida;
}

function ordenarMezcla(registros) {
  if (registros.length < 2) return registros.slice();
  const medio = Math.floor(registros.length / 2);
  const izquierda = ordenarMezcla(registros.slice(0, medio));
  const derecha = ordenarMezcla(registros.slice(medio));
  return mezclarHorarios(izquierda, derecha);
}

function bajarMonticulo(datos, i, tamano, compara) {
  while (2 * i + 1 < tamano) {
    const izquierdo = 2 * i + 1;
    const derecho = izquierdo + 1;
    const hijo =
      derecho < tamano && compara(datos[derecho], datos[izquierdo]) < 0
        ? derecho
        : izquierdo;
    if (compara(datos[hijo], datos[i]) >= 0) return;
    [datos[i], datos[hijo]] = [datos[hijo], datos[i]];
    i = hijo;
  }
}

function construirMonticulo(datos, compara) {
  const copia = datos.slice();
  for (let i = Math.floor(copia.length / 2) - 1; i >= 0; i--)
    bajarMonticulo(copia, i, copia.length, compara);
  return copia;
}

function crearColaPrioridad(datos, compara) {
  const heap = construirMonticulo(datos, compara);
  return {
    tamano: () => heap.length,
    ver: () => heap[0] ?? null,
    agregar(valor) {
      heap.push(valor);
      let i = heap.length - 1;
      while (i > 0) {
        const padre = Math.floor((i - 1) / 2);
        if (compara(heap[i], heap[padre]) >= 0) break;
        [heap[i], heap[padre]] = [heap[padre], heap[i]];
        i = padre;
      }
    },
    extraer() {
      if (!heap.length) return null;
      const primero = heap[0];
      const ultimo = heap.pop();
      if (heap.length) {
        heap[0] = ultimo;
        bajarMonticulo(heap, 0, heap.length, compara);
      }
      return primero;
    },
  };
}

function agendaInicial(viajes) {
  return ordenarMezcla(viajes.map(([id, origen, salida]) => [salida, id]));
}

function simularLlegadas(viajes, hasta) {
  const eventos = viajes.map((viaje, i) => [viaje[2], i, i, 0]);
